# 공항코드 → airportal 지역 (일본/중국/아시아/미주/유럽/대양주/기타)
JP="KIX KMQ UKB KMJ KUH NGS NGO KIJ TAK NRT HND TKS TOY CTS SDJ SYO SHM SHI FSZ HSG MMJ MYJ KMI MSJ AKJ AOJ OKJ OKA OBO OSN OIT OKO YGJ UBJ IBR ISG IZO KOJ KKJ HNA HKD HIJ FKS FUK".split()
CN="KWL CAN KWE KHN NTG NKG NGB PKX DLC DAT DNH LHW LJG LYI MDG BAV PEK SYX XMN SZX SJW XIY SHE YTY EHU YNJ YNT YNZ DSN ENH WDS URC WUX WUS WUH WHA WNZ YCU WEH UYN YIH JMU DYG CGQ CGO TNA CSX TSN TAO CTU CKG BAR KMG TYN TFU TXN PVG FOC HRB HAK HLD HGH HFE SHA HET".split()
AS="VCA CXR DAD DAC DLI DPS DEL RMQ RGN LGK LPQ MDC MNL MFM MZG BOM BTH BWN BPN BKK ULN SUB SIN TSA SAI REP AMD CGK KHH KTM KLO BKI CMB KUL KCH CRK TPE TAG KTI MAA CNX PKZ PEN HKT PQC PNH HAN HPH HKG HUN HUI SGN UTP DMK UBN MPH MXV CEB VTE KNH NKW".split()  # 2026-10 추가: 진먼(KNH, 대만), 디에고 가르시아(NKW, 인도양 — 여객 0이라 영향 없음)
AM="QQS LAX GDL GSP BNA EWR JFK DFW SSA DTW LAS LFI SDF LIM LCK MAO MIA MEX NLU MLB MEM MTY YUL MSP VBG VCP YVR BHM BOS BFI SCL SJC POA MCC SAN SBD SFO SLC SEA RFD ORD CVG ATL ANC YEG PAE AMB OSC OAK ONT IAD YWG IND YQB YYC GRK YYZ PTY SUU PDX AZA PHX PHL HSV YHZ IAH CHR EIL EDF".split()  # 2026-10 추가: 엘멘도르프(EDF, 알래스카)
EU="NQZ MXP HHN LEJ LHR FCO LUX LIS LGG FRU MAD MRS MST AGP MAN MUC WAW BCN VCE BUD BOJ WRO BRU BSZ VIE ZAZ STN ARN ALA ATH GUW AMS ESB EVN OSL UDJ IST ZAG RZE ZRH KGF CPH CGN TAS CRZ KRW TBS CDG PRG FRA PIK GYD HEL LBD CIT EMA ASB".split()
OC="NAN INU GUM SPN CNS KOA ROR AKL SYD BNE MEL HNL".split()
OT="DMM DOH DXB LOS RUH MCT CMN BAH BSR BEY ADD DWC ALG AMM AUH JED JUB JIB KBL CAI FIH SHJ TLV DSS NBO".split()
AREA={}
for a,l in [('일본',JP),('중국',CN),('아시아',AS),('미주',AM),('유럽',EU),('대양주',OC),('기타',OT)]:
    for c in l:
        assert c not in AREA,c
        AREA[c]=a
def city_area(name):
    code=name[name.rindex('(')+1:-1]
    return AREA.get(code)
